 showModal('quest','NORA · BERGINGSCOÖRDINATOR','Noodstroom',body,status?[leave]:[{label:'Neem de opdracht aan',run:()=>{if(engine.acceptSalvageQuest()){engine.closeModal();hideModal();save();updateHUD();}}},leave]);
