function moveInput(){return {x:(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+stick.x,y:(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+stick.y};}
function autoTarget(){return assistedTarget(engine.state.player,engine.state.world.enemies);}
function target(){return touch.fire||touchMode?autoTarget():renderer.screenToWorld(pointer.x,pointer.y);}
function action(name,fromHotbar=false){if(!playable())return;audio.start();let okay=true;
 if(name==='special')okay=engine.castRight(fromHotbar&&!touchMode?hotbarTarget(engine.state.player.rightAbility,engine.state.player,engine.state.world.enemies):target());if(name==='dash'){const dir=moveInput();okay=engine.dash(dir.x,dir.y);}if(name==='heal')okay=engine.heal();if(name==='antidote')okay=engine.useAntidote();if(name==='ultimate')okay=engine.ultimate();if(name==='interact'){okay=engine.interact();if(okay)save();}
 if(okay&&['heal','antidote'].includes(name))save();
 if(!okay&&name==='heal'&&engine.state.player.healCooldown>0)engine.notice('Verband herlaadt · '+Math.ceil(engine.state.player.healCooldown)+'s');if(!okay&&name==='antidote')engine.notice(engine.state.player.antidoteCooldown>0?'Antidotum herlaadt · '+Math.ceil(engine.state.player.antidoteCooldown)+'s':engine.state.player.antidotes<1?'Geen antidoten · verkrijgbaar bij Jules':'Geen gif om te verwijderen');
 if(!okay&&name==='special'){const p=engine.state.player,id=p.rightAbility,cd=p.spellCd[id]||0;engine.notice(engine.inCamp()?'Veilige zone · verlaat het kamp om aan te vallen':cd>0?SPELLS[id].name+' herlaadt · '+cd.toFixed(1)+'s':p.dashTimer>0?'Aanvallen na je ontwijking':SPELLS[id].name+' vereist '+SPELLS[id].cost+' mana');}if(!okay&&name==='ultimate')engine.notice(engine.inCamp()?'Veilige zone · kernpuls buiten het kamp gebruiken':engine.state.player.ultimateCooldown>0?'Kernpuls herlaadt · '+Math.ceil(engine.state.player.ultimateCooldown)+'s':'Kernpuls laadt door schade en combinaties');
}
