 $('relay-a').hidden=$('relay-b').hidden=area.kind!=='hub'||Boolean(area.side);s.world.relays.forEach(r=>{$('relay-'+r.id.toLowerCase()).className=r.status==='online'?'done':r.status==='defending'?'fighting':'';});$('core-icon').textContent=area.side?'◆ Expeditie':area.kind==='hub'?'◆ Kern':'↗ F · reizen';$('core-icon').className=(area.side?s.world.sideDone:s.world.coreCollected||s.world.coreAvailable)?'done':'';
