function closeJournal(){if(modalKind==='upgrade')engine.deferUpgrade();if(['archive','shop','quest','trialResult','trials'].includes(modalKind))engine.closeModal();hideModal();save();}
$('discipline-label').addEventListener('click',()=>playable()&&showSkills('main'));$('special-button').addEventListener('contextmenu',event=>{event.preventDefault();if(playable())showSkills('right');});document.querySelectorAll('[data-slot]').forEach(b=>b.addEventListener('contextmenu',event=>{event.preventDefault();if(playable())showSkills(b.dataset.slot);}));
$('modal-close').addEventListener('click',closeJournal);$('shop-button').addEventListener('click',()=>playable()&&showShop());
$('new-game').disabled=true;$('new-game').addEventListener('click',chooseDiscipline);$('continue-game').addEventListener('click',()=>loaded&&start(null,true));$('cover-help').addEventListener('click',showHelp);$('equipment-button').addEventListener('click',()=>playable()&&showEquipment());$('skills-button').addEventListener('click',()=>playable()&&showSkills());$('level-label').addEventListener('click',()=>playable()&&showSkills());$('pause-button').addEventListener('click',()=>modalKind==='pause'?hideModal():pauseMenu());$('brand').addEventListener('click',event=>{event.preventDefault();pauseMenu();});$('sound-button').addEventListener('click',()=>{audio.start();const muted=audio.toggle();$('sound-button').innerHTML=icon(muted?'mute':'sound');$('sound-button').setAttribute('aria-label',muted?'Geluid inschakelen':'Geluid uitschakelen');});$('map-button').addEventListener('click',()=>playable()&&showAtlas());$('dismiss-tutorial').addEventListener('click',()=>$('tutorial').hidden=true);$('interaction').addEventListener('click',()=>action('interact'));
 document.querySelectorAll('[data-slot]').forEach(button=>button.addEventListener('click',()=>{if(!playable())return;const slot=Number(button.dataset.slot);if(!engine.state.player.hotbar[slot]){showSkills(slot);return;}audio.start();if(!engine.castSlot(slot,touchMode?autoTarget():hotbarTarget(engine.state.player.hotbar[slot],engine.state.player,engine.state.world.enemies)))engine.notice(engine.inCamp()?'Veilige zone · verlaat het kamp om te casten':'Spreuk laadt op of heeft meer mana nodig');}));document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>action(button.dataset.action,true)));
window.addEventListener('keydown',event=>{
 const key=event.key.toLowerCase();if(['SELECT','INPUT','TEXTAREA'].includes(event.target?.tagName)&&key!=='tab')return;if(playable()&&[' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))event.preventDefault();
 if(key==='tab'&&modalKind){const buttons=[...$('modal-layer').querySelectorAll('button:not(:disabled),select:not(:disabled)')];if(buttons.length){const current=buttons.indexOf(document.activeElement),next=(current+(event.shiftKey?-1:1)+buttons.length)%buttons.length;event.preventDefault();buttons[next].focus();}return;}
 if(event.repeat)return;
 if(key==='escape'){if(['help','pause','equipment','skills','atlas','codex','discipline','arrival','error','upgrade','archive','shop','quest','trialResult','trials'].includes(modalKind))closeJournal();else if(playable())pauseMenu();return;}
 if(!playable())return;keys.add(key);
 if(['1','2','3','4','5','6'].includes(key)){const slot=Number(key)-1;if(!engine.state.player.hotbar[slot])showSkills(slot);else engine.castSlot(slot,pointer.active?target():touchMode?autoTarget():null);}
 if(key==='q')action('special');if(key===' '||key==='e')action('dash');if(key==='h')action('heal');if(key==='j')action('antidote');if(key==='r')action('ultimate');if(key==='f')action('interact');if(key==='i')showEquipment();if(key==='m')showAtlas();if(key==='k')showSkills();if(key==='b'&&engine.canTrade())showShop();
});window.addEventListener('keyup',event=>keys.delete(event.key.toLowerCase()));
$('world').addEventListener('pointermove',event=>{pointer.x=event.clientX;pointer.y=event.clientY;pointer.active=true;$('aim-cursor').style.left=pointer.x+'px';$('aim-cursor').style.top=pointer.y+'px';});
function pressAttack(event){if(!playable())return;event.preventDefault();pointer.x=event.clientX;pointer.y=event.clientY;pointer.active=true;audio.start();if(event.button===0)pointer.shoot=true;if(event.button===2){action('special');pointer.right=true;}}
// Mouse mousedown fires for each button, even while another button is held.
$('world').addEventListener('mousedown',pressAttack);window.addEventListener('mouseup',event=>{if(event.button===0)pointer.shoot=false;if(event.button===2)pointer.right=false;});
$('world').addEventListener('pointerdown',event=>{if(event.pointerType==='touch'||event.pointerType==='pen')pressAttack(event);});window.addEventListener('pointerup',event=>{if(event.pointerType==='touch'||event.pointerType==='pen'){pointer.shoot=false;pointer.right=false;}});$('world').addEventListener('pointercancel',clearInput);$('world').addEventListener('contextmenu',event=>event.preventDefault());
$('world').addEventListener('wheel',event=>{if(!playable())return;event.preventDefault();const names=engine.state.player.skills.filter(id=>SPELLS[id]),index=names.indexOf(engine.state.player.spell);engine.selectSpell(names[(index+(event.deltaY>0?1:names.length-1))%names.length]);},{passive:false});
const joystick=$('joystick'),knob=joystick.querySelector('i');let stickPointer=null;
function moveStick(event){if(event.pointerId!==stickPointer)return;const rect=joystick.getBoundingClientRect(),dx=event.clientX-rect.left-rect.width/2,dy=event.clientY-rect.top-rect.height/2,len=Math.hypot(dx,dy),limit=Math.min(1,36/(len||1));knob.style.transform=`translate(${dx*limit}px,${dy*limit}px)`;stick.x=clamp(dx/36,-1,1);stick.y=clamp(dy/36,-1,1);}
joystick.addEventListener('pointerdown',event=>{if(!playable())return;event.preventDefault();stickPointer=event.pointerId;joystick.setPointerCapture(event.pointerId);moveStick(event);$('tutorial').hidden=true;});joystick.addEventListener('pointermove',moveStick);
function releaseStick(event){if(event.pointerId!==stickPointer)return;stickPointer=null;stick.x=stick.y=0;knob.style.transform='';}joystick.addEventListener('pointerup',releaseStick);joystick.addEventListener('pointercancel',releaseStick);
$('touch-fire').addEventListener('pointerdown',event=>{if(!playable())return;event.preventDefault();touch.fire=true;audio.start();$('touch-fire').setPointerCapture(event.pointerId);});for(const name of ['pointerup','pointercancel'])$('touch-fire').addEventListener(name,()=>touch.fire=false);
window.addEventListener('blur',()=>{clearInput();if(playable())pauseMenu();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(playable())pauseMenu();save();}});window.addEventListener('beforeunload',save);window.addEventListener('resize',()=>renderer.resize());
function frame(now){const delta=clamp((now-last)/1000,0,.04);last=now;if(loaded){
 if(playable()){const move=moveInput();let aim=pointer.active?renderer.screenToWorld(pointer.x,pointer.y):null;if(touch.fire)aim=autoTarget();engine.update(delta,{...move,aim,shoot:pointer.shoot||touch.fire,slots:['1','2','3','4','5','6'].filter(k=>keys.has(k)).map(k=>Number(k)-1),right:pointer.right||keys.has('q')});
  if(!pointer.active&&!touch.fire&&!['1','2','3','4','5','6'].some(k=>keys.has(k))&&engine.state.player.moving)engine.state.player.aim=normal(move.x,move.y);if(engine.state.runTime>12&&engine.state.runTime<13){$('tutorial-text').textContent='Richt in het veld en schiet met links of 1–6. Getij maakt nat; storm geleidt. K: skills instellen.';}
 }
 for(const event of engine.takeEvents()){audio.event(event);if(event.type==='trialrecord'){try{localStorage.setItem(RECORD_KEY,JSON.stringify(event.records));}catch{}}if(event.type==='discovery')announceLoot(event);if(event.type==='levelready'){announceLevel(event.level);renderer.kick(3);}if(event.type==='zone'){renderer.reset(engine.state.player);audio.setZone(engine.state.zone);$('tutorial-text').textContent='F: doorgang of vondst · M: wereldkaart · K: vaardigheden · I: rugzak';}if(['special','combo'].includes(event.type))renderer.kick(2);if(event.type==='hurt'){renderer.kick(6);$('damage-flash').classList.add('hit');setTimeout(()=>$('damage-flash').classList.remove('hit'),180);}if(event.type==='ultimate')renderer.kick(5);if(event.type==='ultimpact')renderer.kick(13);}
 audio.setTension(started&&playable()&&!engine.inCamp()?engine.state.world.enemies.filter(e=>!e.dead&&e.awake).length>0?1:0:0);renderer.render(engine,now/1000,delta);if(started){pendingModal();hudTick+=delta;if(hudTick>.08){updateHUD();hudTick=0;}if(now-lastSave>8000){save();lastSave=now;}}
 }requestAnimationFrame(frame);}
refreshContinue();renderer.resize();requestAnimationFrame(frame);
renderer.load().then(()=>{loaded=true;renderer.reset(engine.state.player);$('new-game').disabled=false;$('load-status').textContent='16 hoofdstukken · 11 spreuken · 3 endgame-arena’s';}).catch(error=>{console.error(error);$('load-status').textContent='De spelbeelden konden niet laden. Vernieuw de pagina en probeer opnieuw.';});
